// Fasst Webhook-Input + Jina-Reader-Text + News-RSS-Items zu einem
// AccountEnrichmentRequest-Objekt zusammen (siehe webhook-payload-schema.json).
const webhookItem = $('Webhook \u2013 Neuer Account').first().json;
const body = webhookItem.body || webhookItem;

const companyName = body.company_name;
let domain = (body.domain || '').trim();
if (domain && !domain.startsWith('http')) domain = 'https://' + domain;

const dataGaps = [];

let websiteText = '';
const jinaItem = $('Jina Reader \u2013 Website').first().json;
if (jinaItem && jinaItem.error) {
  dataGaps.push(`Website nicht erreichbar: ${jinaItem.error}`);
} else {
  websiteText = (jinaItem && (jinaItem.data || jinaItem.body || jinaItem.text)) || '';
  if (typeof websiteText !== 'string') websiteText = JSON.stringify(websiteText);
  websiteText = websiteText.slice(0, 20000);
  if (!websiteText.trim()) dataGaps.push('Jina Reader lieferte leeren Website-Text.');
}

let newsItems = [];
try {
  const rssInput = $('Google News RSS').all();
  newsItems = rssInput
    .filter((i) => !i.json.error)
    .slice(0, 5)
    .map((i) => ({
      title: i.json.title || '',
      source: i.json.creator || 'Google News',
      published_at: i.json.pubDate || i.json.isoDate || '',
      snippet: i.json.contentSnippet || i.json.content || '',
      link: i.json.link || '',
    }));
} catch (e) {
  dataGaps.push('News-Feed konnte nicht gelesen werden.');
}
if (newsItems.length === 0) dataGaps.push(`Keine News-Treffer f\u00fcr '${companyName}' gefunden.`);

return [{
  json: {
    company_name: companyName,
    domain,
    raw_website_text: websiteText,
    raw_news_items: newsItems,
    manual_social_insights: body.manual_social_insights || null,
    existing_pitch_notes: body.existing_pitch_notes || null,
    data_gaps: dataGaps,
  },
}];

// Extrahiert den Text-Block aus der Claude-Response und parsed ihn als JSON.
// Fällt bei Parse-Fehlern auf ein gültiges Fallback-Objekt zurück (crasht nie).
const response = $json;
let text = '';
try {
  const block = (response.content || []).find((b) => b.type === 'text');
  text = block ? block.text : '';
} catch (e) {
  text = '';
}

let analysis;
try {
  analysis = JSON.parse(text);
} catch (e) {
  analysis = {
    branche: 'Sonstige',
    mitarbeiterzahl_schaetzung: null,
    key_metrics_ansprechpartner: '',
    news_trigger_events: '',
    pitch_ansatz: { budget: '', authority: '', need: '', timing: '', pain_points: [], icebreaker: '' },
    confidence: 'niedrig',
    data_gaps: ['KI-Antwort konnte nicht als JSON geparst werden.'],
  };
}

return [{ json: analysis }];

// Mappt das EnrichmentResult + den Webhook-Input auf Notion-Property-Typen
// (siehe notion-database-schema.json). Chunked Rich-Text auf <=1900 Zeichen.
const analysis = $json;
const webhookItem = $('Webhook \u2013 Neuer Account').first().json;
const body = webhookItem.body || webhookItem;
const payload = $('LLM-Payload bauen').first().json;

function chunkRichText(text) {
  text = text || '';
  if (!text) return [];
  const chunks = [];
  for (let i = 0; i < text.length; i += 1900) chunks.push(text.slice(i, i + 1900));
  return chunks.map((c) => ({ type: 'text', text: { content: c } }));
}

const pitch = analysis.pitch_ansatz || {};
const painPoints = (pitch.pain_points || []).map((p) => `  \u2022 ${p}`).join('\n') || '  \u2022 \u2014';
let pitchText = `BANT-Analyse\nBudget: ${pitch.budget || ''}\nAuthority: ${pitch.authority || ''}\nNeed: ${pitch.need || ''}\nTiming: ${pitch.timing || ''}\nPain Points:\n${painPoints}\n\nIcebreaker: ${pitch.icebreaker || ''}`;

const dataGaps = [...(payload.data_gaps || []), ...(analysis.data_gaps || [])];
if (dataGaps.length) {
  pitchText += `\n\nDatenl\u00fccken:\n${dataGaps.map((g) => `  \u2022 ${g}`).join('\n')}`;
}

const properties = {
  'Unternehmensname': { title: [{ type: 'text', text: { content: body.company_name } }] },
  'Domain / URL': { url: payload.domain },
  'Branche': { select: { name: analysis.branche || 'Sonstige' } },
  'Key Metrics & C-Level': { rich_text: chunkRichText(analysis.key_metrics_ansprechpartner) },
  'Manuelle Social Insights (LinkedIn)': { rich_text: chunkRichText(body.manual_social_insights || '') },
  'News & Trigger-Events (Auto)': { rich_text: chunkRichText(analysis.news_trigger_events) },
  'Pitch-Ansatz / Icebreaker (AI)': { rich_text: chunkRichText(pitchText) },
  'Status': { select: { name: (analysis.confidence && analysis.confidence !== 'niedrig') ? 'Angereichert' : 'In Recherche' } },
  'Letzte Anreicherung': { date: { start: new Date().toISOString().slice(0, 10) } },
};

if (analysis.mitarbeiterzahl_schaetzung !== null && analysis.mitarbeiterzahl_schaetzung !== undefined) {
  properties['Mitarbeiterzahl'] = { number: analysis.mitarbeiterzahl_schaetzung };
}

return [{ json: { properties } }];
